'use strict';
const $=s=>document.querySelector(s), money=n=>'₹'+n.toLocaleString('en-IN');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let menu=[],cart=[],category='Momos',diet='all',search='',choices={};
const validRows=rows=>Array.isArray(rows)?rows.filter(r=>r&&typeof r.id==='string'&&Number.isInteger(r.variant)&&Number.isInteger(r.qty)&&r.qty>0&&r.qty<=99&&typeof r.butter==='boolean').filter(r=>{let i=menu.find(i=>i.id===r.id);return i?.available&&i.variants[r.variant]?.enabled&&(!r.butter||i.butterEligible)}).map(r=>({id:r.id,variant:r.variant,butter:r.butter,qty:r.qty})):[];
function loadStored(key){try{return validRows(JSON.parse(localStorage.getItem(key)||'[]'))}catch{return []}}
const itemOf=r=>menu.find(i=>i.id===r.id), priceOf=r=>itemOf(r).variants[r.variant].price+(r.butter?10:0), total=()=>cart.reduce((s,r)=>s+priceOf(r)*r.qty,0);
function marker(v){return `<span class="foodlabel"><i class="foodmark ${v.diet}" aria-hidden="true"></i>${v.diet==='veg'?'Vegetarian':'Non-vegetarian'}${v.protein==='egg'?' · Egg':''}</span>`}
function allowed(v){return diet==='all'||diet===v.diet||diet===v.protein}
function renderMenu(){
 $('#categories').innerHTML=['All dishes',...new Set(menu.map(i=>i.category))].map(c=>`<button data-category="${esc(c)}" class="${category===c?'selected':''}" aria-pressed="${category===c}">${esc(c)}</button>`).join('');
 let filtered=menu.filter(i=>(category==='All dishes'||i.category===category)&&i.name.toLowerCase().includes(search.toLowerCase())&&i.variants.some(allowed));
 $('#menucontent').innerHTML=filtered.length?`<div class="menuheading"><h3>${esc(category)}</h3><span>${filtered.length} dishes</span></div><div class="dishgrid">${filtered.map(i=>{
 let permitted=i.variants.map((v,n)=>({v,n})).filter(x=>allowed(x.v));let choice=choices[i.id]||{variant:permitted[0].n,butter:false,qty:1};if(!allowed(i.variants[choice.variant]))choice.variant=permitted[0].n;choices[i.id]=choice;let v=i.variants[choice.variant];return `<article class="dish" id="${i.id}"><div class="dishmeta">${marker(v)}<a class="share" href="#dish=${i.id}" aria-label="Link to ${esc(i.name)}">↗</a></div><h3>${esc(i.name)}</h3><p class="categorylabel">${esc(i.category)}</p>${i.variants.length>1?`<label class="sr" for="variant-${i.id}">Variant for ${esc(i.name)}</label><select id="variant-${i.id}" data-variant="${i.id}">${permitted.map(({v,n})=>`<option value="${n}" ${choice.variant===n?'selected':''}>${v.name} · ${money(v.price)}${!v.enabled?' · Awaiting confirmation':''}</option>`).join('')}</select>`:''}${i.butterEligible?`<label class="butter"><input type="checkbox" data-butter="${i.id}" ${choice.butter?'checked':''}> Add butter <span>+₹10</span></label>`:''}${!i.available||!v.enabled?`<p class="pending">Awaiting menu confirmation</p>`:''}<div class="dishbottom"><strong>${money(v.price+(choice.butter?10:0))}</strong><div class="addcontrols"><label class="sr" for="qty-${i.id}">Quantity of ${esc(i.name)}</label><input id="qty-${i.id}" type="number" min="1" max="99" value="${choice.qty}" data-qty="${i.id}" ${!i.available||!v.enabled?'disabled':''}><button data-add="${i.id}" ${!i.available||!v.enabled?'disabled':''}>Add +</button></div></div></article>`}).join('')}</div>`:`<div class="empty"><h3>No cravings found.</h3><p>Try a different search or filter.</p><button id="resetfilters" class="outline">Reset filters</button></div>`;
}
function save(){try{localStorage.setItem('rao-cart-v1',JSON.stringify(cart))}catch{}$('#count').textContent=cart.reduce((s,r)=>s+r.qty,0);$('#mobiletotal').textContent=money(total());$('#mobilecart').hidden=cart.length===0;renderCart();$('#review').hidden=true}
function add(id){let i=menu.find(i=>i.id===id),c=choices[id];if(!i?.available||!c||!i.variants[c.variant]?.enabled)return;let qty=Math.min(99,Math.max(1,Math.trunc(Number(c.qty))||1));let existing=cart.find(r=>r.id===id&&r.variant===c.variant&&r.butter===c.butter);if(existing)existing.qty=Math.min(99,existing.qty+qty);else cart.push({id,variant:c.variant,butter:c.butter,qty});save();showSuggestion(i)}
function showSuggestion(i){let side=menu.find(x=>x.name==='French Fries');$('#toast').hidden=false;$('#toast').innerHTML=`<span>${esc(i.name)} added.</span><span>Add a side? French Fries · ₹120</span><button id="addside">Add fries +</button><button id="dismiss" aria-label="Dismiss suggestion">✕</button>`;$('#dismiss').onclick=()=>$('#toast').hidden=true;$('#addside').onclick=()=>{choices[side.id]={variant:0,butter:false,qty:1};add(side.id);$('#toast').innerHTML='<span>French Fries added.</span><button id="dismiss" aria-label="Dismiss notification">✕</button>';$('#dismiss').onclick=()=>$('#toast').hidden=true}}
function renderCart(){ $('#cartlines').innerHTML=cart.length?cart.map((r,n)=>{let i=itemOf(r),v=i.variants[r.variant];return `<div class="cartline"><div>${marker(v)}<h3>${esc(i.name)}</h3><p>${v.name}${r.butter?' · Extra butter +₹10':''} · ${money(priceOf(r))} each</p><button class="remove" data-remove="${n}" aria-label="Remove ${esc(i.name)}">Remove</button></div><div class="lineend"><strong>${money(priceOf(r)*r.qty)}</strong><div class="quantity"><button data-change="${n}" data-delta="-1" aria-label="Decrease ${esc(i.name)}">−</button><span>${r.qty}</span><button data-change="${n}" data-delta="1" aria-label="Increase ${esc(i.name)}">+</button></div></div></div>`}).join(''):'<div class="empty"><h3>Your bag is waiting.</h3><p>Pick a flavour from the menu to get started.</p></div>';$('#subtotal').textContent=money(total());$('#orderform').hidden=!cart.length;$('#clearcart').hidden=!cart.length;$('#again').hidden=!loadStored('rao-last-order-v1').length;}
function openCart(){renderCart();$('#cartdialog').showModal()}
function messageFor(form){return ['Hello Rao Butter Momos, I would like to place an order.',`Name: ${form.get('customer').trim()}`,`Phone: ${form.get('phone').trim()}`,'Order type: Takeaway',form.get('pickup')?`Preferred pickup time: ${form.get('pickup')}`:'','Items:',...cart.map(r=>`${r.qty} × ${itemOf(r).name} (${itemOf(r).variants[r.variant].name}${r.butter?', extra butter':''}) — ${money(priceOf(r)*r.qty)}`),`Menu subtotal: ${money(total())}`,form.get('notes').trim()?`Notes: ${form.get('notes').trim()}`:'','Please confirm availability, final charges and pickup time.'].filter(Boolean).join('\n')}
function updateLink(){$('#sendorder').href='https://wa.me/917065908203?text='+encodeURIComponent('Hello Diwanshu, I liked your Rao Butter Momos concept and would like to discuss a website for my business.')} 
$('#navtoggle').onclick=()=>{let n=$('#nav');n.classList.toggle('open');$('#navtoggle').setAttribute('aria-expanded',n.classList.contains('open'))};$('#nav').onclick=e=>{if(e.target.closest('a')){$('#nav').classList.remove('open');$('#navtoggle').setAttribute('aria-expanded','false')}};
$('#search').oninput=e=>{search=e.target.value;if(search)category='All dishes';renderMenu()};$('.dietfilters').onclick=e=>{let b=e.target.closest('[data-diet]');if(!b)return;diet=b.dataset.diet;document.querySelectorAll('[data-diet]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});renderMenu()};$('#categories').onclick=e=>{let b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;history.replaceState(null,'','#category='+encodeURIComponent(category));renderMenu()};
$('#menucontent').oninput=e=>{let t=e.target;if(t.dataset.qty)choices[t.dataset.qty].qty=Math.min(99,Math.max(1,Math.trunc(Number(t.value))||1))};
$('#menucontent').onchange=e=>{let t=e.target;if(t.dataset.variant){choices[t.dataset.variant].variant=Number(t.value);renderMenu()}if(t.dataset.butter){choices[t.dataset.butter].butter=t.checked;renderMenu()}if(t.dataset.qty){choices[t.dataset.qty].qty=Math.min(99,Math.max(1,Math.trunc(Number(t.value))||1));t.value=choices[t.dataset.qty].qty}};
$('#menucontent').onclick=e=>{let b=e.target.closest('[data-add]');if(b)add(b.dataset.add);if(e.target.id==='resetfilters'){diet='all';search='';category='All dishes';$('#search').value='';document.querySelector('[data-diet="all"]').click()}};
$('#cartlines').onclick=e=>{let b=e.target.closest('[data-remove],[data-change]');if(!b)return;if(b.dataset.remove!==undefined)cart.splice(Number(b.dataset.remove),1);else {let n=Number(b.dataset.change);cart[n].qty=Math.min(99,cart[n].qty+Number(b.dataset.delta));if(cart[n].qty<=0)cart.splice(n,1)}save()};
document.querySelectorAll('.cartopen').forEach(b=>b.onclick=openCart);$('.close').onclick=()=>$('#cartdialog').close();$('#clearcart').onclick=()=>{cart=[];save()};$('#again').onclick=()=>{cart=loadStored('rao-last-order-v1');save()};
$('#orderform').onsubmit=e=>{e.preventDefault();if(!cart.length)return;let f=new FormData(e.target),p=f.get('phone').replace(/\D/g,'');let valid=(p.length===10&&/^[6-9]/.test(p))||(p.length===12&&/^91[6-9]/.test(p));e.target.phone.setCustomValidity(valid?'':'Enter a 10-digit Indian mobile number, optionally prefixed with +91.');e.target.customer.setCustomValidity(f.get('customer').trim()?'':'Enter your name.');if(!e.target.reportValidity())return;$('#message').value=messageFor(f);$('#review').hidden=false;updateLink();$('#review').scrollIntoView({block:'nearest'});$('#message').focus()};$('#orderform').oninput=e=>{e.target.setCustomValidity?.('');$('#review').hidden=true};$('#message').oninput=updateLink;$('#sendorder').onclick=()=>{try{localStorage.setItem('rao-last-order-v1',JSON.stringify(cart))}catch{} };$('#copyorder').onclick=async()=>{try{await navigator.clipboard.writeText($('#message').value);$('#copyorder').textContent='Copied ✓'}catch{$('#message').focus();$('#message').select();$('#copyorder').textContent='Select and copy the message'}};
function applyHash(){let h=location.hash.slice(1);if(h.startsWith('category=')){let c;try{c=decodeURIComponent(h.slice(9))}catch{return;}if(c==='All dishes'||menu.some(i=>i.category===c)){category=c;renderMenu();$('#menu').scrollIntoView()}}if(h.startsWith('dish=')){let id=h.slice(5);if(menu.some(i=>i.id===id)){category='All dishes';diet='all';search='';$('#search').value='';document.querySelector('[data-diet="all"]').click();renderMenu();document.getElementById(id)?.scrollIntoView()}}}window.addEventListener('hashchange',applyHash);
fetch('menu.json').then(r=>{if(!r.ok)throw Error('Menu unavailable');return r.json()}).then(data=>{menu=data;cart=loadStored('rao-cart-v1');renderMenu();save();applyHash();if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_menu_and_cart',description:'Read restaurant menu variants, prices, confirmation status and the current device-local bag.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||typeof input!=="object"||Array.isArray(input)||Object.keys(input).length)throw new Error("Expected an empty input object");return {menu,cart,subtotal:total()}}})).catch(()=>{})}catch{}}}).catch(()=>{$('#menucontent').insertAdjacentHTML('afterbegin','<p class="notice">Interactive ordering is temporarily unavailable. The menu is below; this concept does not accept orders.</p>')});
